```cpp
#include <algorithm>
#include <iostream>
#include <map>
#include <numeric>
#include <string>
#include <vector>

struct Expense {
    int id;
    std::string title;
    std::string category;
    double amount;
};

class ExpenseRepository {
public:
    void add(Expense expense) { expenses.push_back(std::move(expense)); }
    void remove(int id) {
        expenses.erase(std::remove_if(expenses.begin(), expenses.end(),
            [id](const Expense& item) { return item.id == id; }), expenses.end());
    }
    const std::vector<Expense>& all() const { return expenses; }
private:
    std::vector<Expense> expenses;
};

class ExpenseService {
public:
    explicit ExpenseService(ExpenseRepository& repository) : repository(repository) {}
    std::map<std::string, double> summary() const {
        std::map<std::string, double> result;
        for (const auto& item : repository.all()) result[item.category] += item.amount;
        return result;
    }
private:
    ExpenseRepository& repository;
};

int main() {
    ExpenseRepository repository;
    repository.add({1, "Lunch", "Food", 12.5});
    repository.add({2, "Bus", "Transport", 2.0});
    ExpenseService service(repository);
    for (const auto& [category, total] : service.summary())
        std::cout << category << ": " << total << std::endl;
}
```
