```python
from dataclasses import dataclass, field
from collections import defaultdict

@dataclass
class Expense:
    id: int
    title: str
    category: str
    amount: float

@dataclass
class ExpenseRepository:
    expenses: list[Expense] = field(default_factory=list)

    def add(self, expense: Expense) -> None:
        self.expenses.append(expense)

    def remove(self, expense_id: int) -> None:
        self.expenses = [item for item in self.expenses if item.id != expense_id]

    def total(self) -> float:
        return sum(item.amount for item in self.expenses)

    def totals_by_category(self) -> dict[str, float]:
        totals: dict[str, float] = defaultdict(float)
        for item in self.expenses:
            totals[item.category] += item.amount
        return dict(totals)

class ExpenseService:
    def __init__(self, repository: ExpenseRepository) -> None:
        self.repository = repository

    def add_expense(self, title: str, category: str, amount: float) -> None:
        next_id = len(self.repository.expenses) + 1
        self.repository.add(Expense(next_id, title, category, amount))

    def print_summary(self) -> None:
        for category, total in self.repository.totals_by_category().items():
            print(f"{category}: {total:.2f}")
        print(f"Total: {self.repository.total():.2f}")

repository = ExpenseRepository()
service = ExpenseService(repository)
service.add_expense("Lunch", "Food", 12.5)
service.add_expense("Bus", "Transport", 2.0)
service.add_expense("Coffee", "Food", 4.5)
service.print_summary()
```
